317	/**
318	 * Something changed in Prelude: say so down the app's channel, so the home
319	 * page's regions reload (R-p6r), and push the bar's count afresh. Sent once
320	 * the request that changed it is answered, never holding it up. `running`:
321	 * an app run from a project's page started, answered or stopped (runs.js).
322	 * `architecture`: a turn's check read the code again (architecture.js), so
323	 * the Architecture page's check reloads.
324	 */
325	export function tell(app, { needs = false, projects = false, running = false, architecture = false }) {
326	  if (needs) app.waiting = null;
327	  setImmediate(() => {
328	    if (!app.live.listening(APP_CHANNEL)) return;
329	    try {
330	      if (needs) app.live.publish(APP_CHANNEL, 'needs-changed');
331	      if (projects) app.live.publish(APP_CHANNEL, 'projects-changed');
332	      if (running) app.live.publish(APP_CHANNEL, 'app-changed');
333	      if (architecture) app.live.publish(APP_CHANNEL, 'architecture-checked');
334	      if (needs) app.live.publish(APP_CHANNEL, `<div ko-into="waiting">${render('./_waiting', { needsYou: waitingOf(app) }).trim()}</div>`);
335	    } catch (error) { console.error(error); }
336	  });
337	}
